"""Generate the post-enquiry page using the site's shared shell and original villa studio."""
from pathlib import Path
from studio_content import studio
import re
root=Path(__file__).resolve().parent.parent
source=(root/'contact.html').read_text()
head=source[:source.index('<main id="main">')].replace(' aria-current="page"','')
head=re.sub(r'<title>.*?</title>','<title>Thank you | Leaf Infra</title>',head)
head=re.sub(r'<link rel="canonical"[^>]*>','<meta name="robots" content="noindex,follow">',head)
head=re.sub(r'<meta property="og:title"[^>]*>', '<meta property="og:title" content="Your next chapter | Leaf Infra">', head)
head=re.sub(r'<meta property="og:url"[^>]*>', '<meta property="og:url" content="https://leafinfra.com/thank-you">', head)
head=head.replace('</head>','<script src="/assets/thank-you.js" defer></script></head>')
footer=source[source.index('</main>'):]
content='''<main id="main"><section class="thanks-hero"><div class="wrap thanks-grid"><div class="thanks-copy"><span class="eyebrow" id="thanks-eyebrow">THE NEXT CHAPTER / LEAF INFRA</span><div class="thanks-check" aria-hidden="true">↗</div><h1 id="thanks-title">A home worth<br>looking forward to.</h1><p id="thanks-copy">Explore the possibilities while you plan your next step. From a first conversation to a carefully coordinated build, every home starts with your vision.</p><div id="receipt" class="receipt" hidden><span>YOUR ENQUIRY REFERENCE</span><code id="receipt-reference"></code><small>Keep this reference for your next conversation with us.</small></div><div class="thanks-actions"><a class="btn" href="#villa-studio">Explore the villa model ↓</a><a class="text-link" href="/projects">See our project work ↗</a></div></div><div class="thanks-photo"><img src="https://images.pexels.com/photos/13752348/pexels-photo-13752348.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1600" alt="Contemporary villa with expansive glazing, shown as architectural inspiration" width="1200" height="1000"><div class="thanks-photo-label"><span>SPACE TO IMAGINE.</span><b>A home shaped around you.</b><small>Stock villa inspiration · Not a Leaf Infra project · <a href="/photo-credits">Photo credits</a></small></div></div></div></section><section class="thanks-next"><div class="wrap"><span class="eyebrow">A LITTLE PREPARATION GOES A LONG WAY</span><div class="thanks-steps"><article><span>01 / YOUR SITE</span><h2>Keep the essentials ready.</h2><p>Site location, plot size and any existing drawings help shape a useful first discussion.</p></article><article><span>02 / YOUR PRIORITIES</span><h2>Picture life in your home.</h2><p>Think about rooms, family needs, preferred finishes, budget and the timing you have in mind.</p></article><article><span>03 / OUR CONVERSATION</span><h2>Work towards a clear scope.</h2><p>The team can discuss your requirements and what is needed for a project-specific estimate.</p></article></div></div></section>'''
model=studio().replace('<div class="studio-followup">','<div class="studio-followup" hidden>')
content+=model+'''<section class="section soft"><div class="wrap"><div class="section-head"><div><span class="eyebrow">FROM THE CLIENT PORTFOLIO</span><h2>Experience you can see.</h2></div><a class="text-link" href="/projects">Explore the portfolio ↗</a></div><div class="thanks-projects"><figure><img loading="lazy" src="/assets/projects/narayana-vepery.webp" alt="School courtyard from Leaf Infra’s supplied institutional portfolio" width="1152" height="864"><figcaption><b>Institutional spaces</b><span>From the supplied project portfolio</span></figcaption></figure><figure><img loading="lazy" src="/assets/projects/south-east-omr.webp" alt="Residential apartment building from Leaf Infra’s supplied project portfolio" width="960" height="1280"><figcaption><b>Residential construction</b><span>From the supplied project portfolio</span></figcaption></figure></div></div></section>'''
(root/'thank-you.html').write_text(head+content+footer)
